import json

class ProgressRecordError(ValueError):
    pass

def load_progress(text):
    try:
        record = json.loads(text)
    except json.JSONDecodeError as error:
        raise ProgressRecordError('Progress data is not valid JSON.') from error

    if not isinstance(record, dict):
        raise ProgressRecordError('Progress data must be an object.')
    if not isinstance(record.get('learner'), str):
        raise ProgressRecordError('learner must be text.')
    if not isinstance(record.get('completed'), list) or not all(isinstance(x, str) for x in record['completed']):
        raise ProgressRecordError('completed must be a list of lesson IDs.')
    return record

print(load_progress('{"learner": "Asha", "completed": ["loops"]}'))

