import json

def valid_progress(text):
    try:
        record = json.loads(text)
    except json.JSONDecodeError:
        return False
    completed = record.get('completed') if isinstance(record, dict) else None
    return (
        isinstance(record, dict)
        and isinstance(record.get('learner'), str)
        and isinstance(completed, list)
        and all(isinstance(item, str) for item in completed)
    )

print(valid_progress('{"learner": "Asha", "completed": ["loops"]}'))
print(valid_progress('[]'))
